import java.util.*;
public class Solution{public static void main(String[]a){Scanner sc=new Scanner(System.in);String s=sc.nextLine();int wn=Integer.parseInt(sc.nextLine().trim());int n=s.length();boolean[]bold=new boolean[n];for(int k=0;k<wn;k++){String w=sc.nextLine().trim();int wl=w.length();int idx=s.indexOf(w);while(idx>=0){for(int i=idx;i<idx+wl;i++)bold[i]=true;idx=s.indexOf(w,idx+1);}}StringBuilder sb=new StringBuilder();for(int i=0;i<n;i++){if(bold[i]&&(i==0||!bold[i-1]))sb.append("<b>");sb.append(s.charAt(i));if(bold[i]&&(i==n-1||!bold[i+1]))sb.append("</b>");}System.out.println(sb);}}
